static __inline void player_render_set_alive_tint(float tint_alpha)
{
    grim_interface_ptr->grim_set_color(
        1.0f, 1.0f, 1.0f, tint_alpha);
    if (config_player_count > 1) {
        if (render_overlay_player_index == 0) {
            grim_interface_ptr->grim_set_color(
                0.3f, 0.3f, 1.0f, tint_alpha);
        } else {
            grim_interface_ptr->grim_set_color(
                1.0f, 0.55f, 0.35f, tint_alpha);
        }
    }
}

